"""Generate exact-font marketing SVGs and a self-contained specimen landing page.
Run after python release.py build. Optional PNG export requires CairoSVG 2.8.2.
"""
from pathlib import Path
import base64, html
from fontTools.ttLib import TTFont
from fontTools.pens.svgPathPen import SVGPathPen
ROOT=Path(__file__).resolve().parents[1]
OUT=ROOT/'marketing'; ASSETS=OUT/'assets';ASSETS.mkdir(exist_ok=True)
INK='#172a32';PAPER='#f4f1e7';ACID='#dafa72';MUTED='#aec0bd'
fonts={s:TTFont(ROOT/'dist'/f'Damonic-{s}.ttf') for s in ('Regular','Italic','Bold','BoldItalic')}
def text(t,x,y,size=24,color=INK,style='Regular'):
 f=fonts[style]; gs=f.getGlyphSet();cmap=f.getBestCmap();parts=[];cursor=0
 for c in t:
  name=cmap.get(ord(c),'.notdef');pen=SVGPathPen(gs);gs[name].draw(pen)
  parts.append(f'<path transform="translate({cursor},0)" d="{pen.getCommands()}"/>');cursor+=f['hmtx'][name][0]
 return f'<g aria-label="{html.escape(t,quote=True)}" fill="{color}" transform="translate({x},{y}) scale({size/1000},-{size/1000})">'+''.join(parts)+'</g>'
def rect(x,y,w,h,fill,rx=0):return f'<rect x="{x}" y="{y}" width="{w}" height="{h}" rx="{rx}" fill="{fill}"/>'
def save(name,w,h,parts):
 svg=f'<svg xmlns="http://www.w3.org/2000/svg" width="{w}" height="{h}" viewBox="0 0 {w} {h}" role="img"><title>Damonic — Make room for the code</title>'+''.join(parts)+'</svg>'
 (ASSETS/(name+'.svg')).write_text(svg)
 try:
  import cairosvg
  cairosvg.svg2png(bytestring=svg.encode(),write_to=str(ASSETS/(name+'.png')))
 except ImportError:pass
# Repository/social preview: type is converted to actual Damonic outlines.
save('damonic-hero',1280,640,[rect(0,0,1280,640,INK),text('DAMONIC / OPEN-SOURCE CODING TYPEFACE',54,56,17,MUTED),rect(1080,30,146,38,ACID,19),text('ALPHA 0.4',1098,55,18),text('Damonic',48,260,190,PAPER),text('Make room for the code.',56,334,37,ACID),rect(56,394,1168,1,'#476069'),text('Regular  Italic  Bold  Bold Italic',56,449,23,PAPER),text('One collection. Complete Nerd Fonts edition.',56,492,23,MUTED),text('FREE / OFL 1.1',56,587,16,ACID),text('github.com/daeon/Damonic',778,587,19,PAPER)])
save('damonic-social',1080,1080,[rect(0,0,1080,1080,PAPER),text('DAMONIC',64,77,25,INK,'Bold'),text('A CODING FONT, OPEN BY DESIGN.',64,162,22),text('Make room',54,317,97),text('for the code.',54,425,80),rect(64,485,952,365,INK,12),text('function makeRoom(input) {',98,548,30,ACID),text('  const ideas = input.map(',98,600,30,PAPER),text('    idea => refine(idea)',98,652,30,PAPER,'Italic'),text('  );',98,704,30,PAPER),text('  return ideas;',98,756,30,ACID),text('}',98,808,30,PAPER),text('4 STYLES / NERD FONT MONO / FREE ALPHA',64,929,22),text('github.com/daeon/Damonic',64,1008,25)])
p=[rect(0,0,1080,1440,INK),text('DAMONIC / TYPE SPECIMEN 01',60,66,20,MUTED),text('Damonic',48,225,180,PAPER),text('Make room for the code.',60,294,35,ACID),rect(60,344,960,1,'#476069')]
for j,(s,label) in enumerate([('Regular','01  REGULAR'),('Italic','02  ITALIC'),('Bold','03  BOLD'),('BoldItalic','04  BOLD ITALIC')]):
 y=401+j*189;p+=[text(label,60,y,17,MUTED),text('printing minimum return',60,y+66,47,PAPER,s),text('Il1 | O0o  {} [] ()  -> => !=',60,y+117,31,ACID,s)]
p += [rect(60,1169,960,1,'#476069'),text('8 FACES. ONE TTC COLLECTION.',60,1231,26,PAPER),text('Base + complete Nerd Fonts 3.5.1 edition.',60,1280,22,MUTED),text('FREE OPEN-SOURCE ALPHA',60,1364,19,ACID),text('github.com/daeon/Damonic',641,1364,22,PAPER)]
save('damonic-specimen',1080,1440,p)
faces='\n'.join("@font-face{font-family:'Damonic"+s+"';src:url(data:font/woff2;base64,"+base64.b64encode((ROOT/'dist'/f'Damonic-{s}.woff2').read_bytes()).decode()+") format('woff2');font-display:swap}" for s in fonts)
page='''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="Damonic is an original open-source coding typeface. Four styles, a complete Nerd Fonts Mono edition, and one eight-face collection. Download the free alpha."><title>Damonic — Make room for the code.</title><style>FONTS
:root{--ink:#172a32;--paper:#f4f1e7;--acid:#dafa72;--muted:#aec0bd}*{box-sizing:border-box}body{margin:0;background:var(--paper);color:var(--ink);font:17px/1.65 system-ui,sans-serif}a{color:inherit;text-underline-offset:4px}a:focus-visible,button:focus-visible,input:focus-visible,select:focus-visible,textarea:focus-visible{outline:3px solid #618500;outline-offset:5px}.wrap{max-width:1240px;margin:auto;padding:0 clamp(22px,5vw,64px)}nav{display:flex;align-items:center;justify-content:space-between;gap:16px;padding-top:27px;padding-bottom:27px;font-size:14px}.wordmark{font:24px DamonicBold;text-decoration:none}.pill{background:var(--acid);padding:5px 12px;border-radius:30px;font-size:12px;white-space:nowrap}.hero{background:var(--ink);color:var(--paper);padding:65px 0 67px}.eyebrow{font:13px/1.5 DamonicRegular;letter-spacing:.12em;color:var(--muted)}h1{font:clamp(39px,7.6vw,91px)/1.15 DamonicRegular;letter-spacing:-.04em;margin:29px 0}h1 em{font-style:normal;color:var(--acid)}.intro{font-size:20px;max-width:630px;color:#d3dfdc}.actions{display:flex;gap:16px;align-items:center;flex-wrap:wrap;margin:31px 0}.button{display:inline-block;text-decoration:none;background:var(--acid);color:var(--ink);padding:13px 22px;border:1px solid var(--acid);border-radius:4px;font-weight:650}.secondary{color:var(--paper);background:transparent;border-color:#6e8287}.micro{font-size:13px;color:var(--muted)}.facts{display:grid;grid-template-columns:repeat(3,1fr);gap:30px;padding-top:38px;padding-bottom:38px;border-bottom:1px solid #b8c2bb}.facts strong{display:block;font:28px DamonicRegular}.facts span{font-size:14px}.section{padding-top:66px;padding-bottom:66px}h2{font:clamp(28px,4vw,42px)/1.2 DamonicRegular;margin:0 0 19px}h3{font-size:20px;margin:0 0 10px}.muted{color:#526665}.controls{display:flex;align-items:center;flex-wrap:wrap;gap:19px;margin:24px 0;font-size:14px}select{padding:8px;color:var(--ink);background:transparent;border:1px solid #82968f;border-radius:4px}input{accent-color:#537500}textarea{display:block;width:100%;height:335px;padding:26px;resize:vertical;white-space:pre;overflow:auto;background:var(--ink);color:var(--paper);border:0;border-radius:8px;font:18px/1.7 DamonicRegular;font-synthesis:none}.glyphs{font:clamp(21px,3.8vw,38px)/1.6 DamonicRegular;border-bottom:1px solid #b8c2bb;padding:30px 0;overflow-wrap:anywhere}.cards{display:grid;grid-template-columns:repeat(3,1fr);gap:32px;margin-top:43px}.number{font:15px DamonicRegular;color:#526665;border-top:2px solid var(--ink);padding-top:19px;margin-bottom:20px}.dark{background:var(--ink);color:var(--paper)}.dark h2{color:var(--acid)}.editions{display:grid;grid-template-columns:1fr 1fr;gap:48px;margin-top:37px}.editions p{color:#d3dfdc}.edition{border-top:1px solid #62767c;padding-top:25px}.note{max-width:760px;font-size:15px}.bottom{display:flex;gap:25px;align-items:center;justify-content:space-between;flex-wrap:wrap}footer{border-top:1px solid #b8c2bb;padding:30px 0;font-size:13px}.links{display:flex;gap:18px;flex-wrap:wrap}@media(max-width:650px){.facts,.cards,.editions{grid-template-columns:1fr}.facts{gap:22px}.facts strong{display:inline-block;min-width:130px}.hero{padding-top:38px}.section{padding-top:45px;padding-bottom:45px}.cards{gap:20px}textarea{padding:17px}nav .navsource{display:none}}
</style></head><body><nav class="wrap"><a class="wordmark" href="#">Damonic</a><div class="links"><span class="pill">0.4.2 ALPHA</span><a class="navsource" href="https://github.com/daeon/Damonic">Source on GitHub ↗</a></div></nav><header class="hero"><div class="wrap"><div class="eyebrow">AN ORIGINAL OPEN-SOURCE CODING TYPEFACE</div><h1>Make room<br>for <em>the code.</em></h1><p class="intro">Humanist letterforms. A fixed-width rhythm. Damonic brings its own character to your editor and terminal.</p><div class="actions"><a class="button" href="https://github.com/daeon/Damonic/releases/tag/v0.4.2-alpha">Download the free alpha ↗</a><a class="button secondary" href="#try">Try the typeface ↓</a></div><p class="micro">Free and open source · OFL 1.1 · TTF + TTC + WOFF2</p></div></header><div class="wrap facts"><div><strong>4 styles</strong><span>Regular, Italic, Bold, Bold Italic</span></div><div><strong>10,624</strong><span>Nerd Fonts symbol mappings</span></div><div><strong>1 collection</strong><span>Eight faces together in a TTC</span></div></div><main><section class="wrap section" id="try"><h2>Your code. Your settings.</h2><p class="muted">Type below. These are the actual Damonic fonts, embedded in this page.</p><div class="controls"><label>Style <select id="style"><option value="Regular">Regular</option><option value="Italic">Italic</option><option value="Bold">Bold</option><option value="BoldItalic">Bold Italic</option></select></label><label>Size <input id="size" type="range" min="12" max="28" value="18"> <output id="size-value">18 px</output></label><label><input id="dlig" type="checkbox"> Ligatures</label><label><input id="ss01" type="checkbox"> Dotted zero</label><label><input id="ss02" type="checkbox"> Simple l</label></div><label for="specimen" class="micro" style="color:#526665">Editable code specimen</label><textarea id="specimen" spellcheck="false" autocapitalize="off">// A little character. Plenty of code.
function makeRoom(input) {
  const ideas = input.map(idea => refine(idea));
  if (ideas.length >= 10 && input[0] != 0) {
    return ideas;
  }
}
// printing minimum return · Il1 | O0o</textarea><div class="glyphs">Aa Bb Cc &amp; @ # →<br>Il1 | O0o {} [] () 0123456789</div><div class="cards"><article><div class="number">01 / CHARACTER</div><h3>Humanist, with structure.</h3><p>Original outlines shaped around a monospaced grid. Four styles give comments, keywords, and emphasis their own voice.</p></article><article><div class="number">02 / CONTROL</div><h3>A few useful choices.</h3><p>Seven optional operator ligatures. A dotted zero. A simpler lowercase l. Enable the features your editor supports.</p></article><article><div class="number">03 / TERMINAL</div><h3>The symbols belong here.</h3><p>Box drawing, blocks, Braille, and Powerline in the base font. The Nerd edition adds the complete mapped Nerd Fonts Symbols Mono 3.5.1 repertoire.</p></article></div></section><section class="dark section"><div class="wrap"><h2>One download.<br>Two ways to work.</h2><div class="editions"><article class="edition"><h3>Damonic</h3><p>The base family: four styles with Latin coverage, terminal characters, and optional OpenType features.</p></article><article class="edition"><h3>Damonic Nerd Font Mono</h3><p>The same letterforms with the full Nerd Fonts Symbols Mono 3.5.1 mapping set, fitted to single terminal cells.</p></article></div><p class="micro">The TTC packages all eight faces. Individual TTFs are included for compatibility. This is a collection of static styles, not a variable font.</p></div></section><section class="wrap section"><div class="bottom"><div><h2>Put it in your editor.</h2><p>Install. Choose a family. Tell us what you notice.</p></div><a class="button" href="https://github.com/daeon/Damonic/releases/tag/v0.4.2-alpha">Get Damonic ↗</a></div><p class="note muted">Damonic is an alpha. Native-platform testing, hinting review, and final optical polish are still underway. Greek and Cyrillic are not included. If something looks off, share your application, size, scaling, and a screenshot.</p><div class="links"><a href="https://github.com/daeon/Damonic/issues">Report an issue</a><a href="https://github.com/daeon/Damonic/blob/main/CONTRIBUTING.md">Contribute</a><a href="https://github.com/daeon/Damonic/blob/main/OFL.txt">Read the license</a></div></section></main><footer><div class="wrap bottom"><span>Damonic · Open by design.</span><span>Original font: OFL 1.1. Nerd symbols retain upstream notices.</span></div></footer><script>
const byId=id=>document.getElementById(id);function update(){const el=byId('specimen');el.style.fontFamily='Damonic'+byId('style').value;el.style.fontSize=byId('size').value+'px';byId('size-value').textContent=byId('size').value+' px';el.style.fontFeatureSettings=['dlig','ss01','ss02'].map(id=>'"'+id+'" '+(byId(id).checked?1:0)).join(',')}document.querySelectorAll('input,select').forEach(el=>el.addEventListener('input',update));update();
</script></body></html>'''
(OUT/'Damonic-Landing.html').write_text(page.replace('FONTS',faces))
print('Built hero, social graphic, specimen poster and embedded-font landing page.')
